	public static String translate(String s) {
		if (s == null || s.isEmpty()) return s;
		String r = map().get(s);
		return r != null ? r : s;
	}

	/** 中英結合：回傳「中文 (English)」。查表失敗則原樣回傳。 */
	public static String translateBilingual(String s) {
		if (s == null || s.isEmpty()) return s;
		String r = map().get(s);
		if (r == null || r.equals(s)) {
			return s;
		}
		return r + " (" + s + ")";
	}

	/** 只取中文譯文（非中英結合）。未命中回傳 null。供 CacheTranslation 萬用 fallback 查詢物品/NPC/Loc 名。 */
	public static String lookupZh(String s) {
		if (s == null || s.isEmpty()) return null;
		String r = map().get(s);
		if (r == null || r.equals(s)) return null;
		return r;
	}

	/** 地圖專用中英結合：回傳「中文<br>(英文)」兩行（WorldMap splitParagraph 依 <br> 換行）。 */
	public static String translateBilingualMap(String s) {
		if (s == null || s.isEmpty()) return s;
		// 先試原樣（含標籤）
		String r = map().get(s);
		// 剝除 <br>/<col> 標籤後查表（<br> 先換成空格，避免 "Lumbridge<br>Castle" 變 "LumbridgeCastle" 查詢失敗）
		String raw = s.replaceAll("<br>", " ").replaceAll("</br>", " ").replaceAll("<[^>]+>", "").trim();
		if ((r == null || r.equals(s)) && !raw.equals(s)) {
			r = map().get(raw);
		}
		if (r == null || r.equals(s)) {
			// 再試去空格（兩行標籤可能被存成無空格）
			String noSpace = raw.replace(" ", "");
			r = map().get(noSpace);
			if (r == null || r.equals(noSpace)) {
				return s;
			}
		}
		// 把中文譯文放進原字串的 <col> 標籤（若原字串含顏色標籤）
		String colorTag = "";
		int ct = s.indexOf("<col");
		if (ct >= 0) {
			int ctEnd = s.indexOf('>', ct);
			if (ctEnd >= 0) {
				colorTag = s.substring(ct, ctEnd + 1);
			}
		}
		String zh = colorTag + r;
		return zh + "<br>(" + s + ")";
	}
